import SwiftUI
struct ApprovalView:View{@EnvironmentObject var store:BudgetStore;let transaction:Transaction;@State var merchant="";@State var date=Date();@State var subtotal:Decimal?;@State var tax:Decimal?;@State var receiptTotal:Decimal?;@State var items:[ReceiptLineItem]=[];@State var reviewed=false;@State var confirm=false
var splitTotal:Decimal{items.reduce(0){$0+$1.total}};var difference:Decimal{abs(transaction.amount)-splitTotal};var balanced:Bool{abs(NSDecimalNumber(decimal:difference).doubleValue)<0.01}
var body:some View{Form{Section("Editable receipt"){TextField("Merchant",text:$merchant);DatePicker("Date",selection:$date,displayedComponents:.date);TextField("Receipt total",value:$receiptTotal,format:.number);TextField("Subtotal",value:$subtotal,format:.number);TextField("VAT",value:$tax,format:.number)};Section("Editable items"){ForEach($items){$item in HStack{TextField("Description",text:$item.description);TextField("Amount",value:$item.total,format:.number).frame(width:100);TextField("Category",text:$item.category);Button(role:.destructive){items.removeAll{$0.id==item.id}}label:{Image(systemName:"trash")}}};Button("Add item"){items.append(ReceiptLineItem(description:"New item",total:0,confidence:1))}};Section("Reconciliation"){LabeledContent("Bank amount",value:abs(transaction.amount) as NSDecimalNumber,format:.currency(code:"GBP"));LabeledContent("Split total",value:splitTotal as NSDecimalNumber,format:.currency(code:"GBP"));LabeledContent("Difference",value:abs(difference) as NSDecimalNumber,format:.currency(code:"GBP"));Label(balanced ? "Balanced":"Adjust items until difference is zero",systemImage:balanced ? "checkmark.circle.fill":"exclamationmark.triangle.fill")};Section("Approval"){Toggle("I have checked every item and category",isOn:$reviewed);HStack{Button("Save Draft Only"){store.saveDraft(makeDraft(),for:transaction)};Spacer();Button("Review and Approve…"){confirm=true}.buttonStyle(.borderedProminent).disabled(!reviewed || !balanced || items.isEmpty)}}}.confirmationDialog("Create these splits?",isPresented:$confirm){Button("Approve and Create \(items.count) Splits"){var d=makeDraft();d.approvedAt=Date();store.approve(d,for:transaction)};Button("Keep Editing",role:.cancel){}}}
func makeDraft()->SplitDraft{let r=ReceiptRecord(imagePath:"",merchant:merchant,purchaseDate:date,subtotal:subtotal,tax:tax,total:receiptTotal,rawText:"",items:items,confidence:1,reviewed:reviewed);return SplitDraft(receipt:r,proposedSplits:items.map{TransactionSplit(label:$0.description,category:$0.category,amount:$0.total)})}}
